INSERT INTO `subject` (`id`, `name`, `content`, `images`, `courseId`) VALUES
(6, 'Social Engineering', '                   Social Engineering หรือ วิศวกรรมทางสังคม เป็นเทคนิคการโจมตีแบบหนึ่งของการโจมตีทางไซเบอร์ที่ไม่ต้องพึ่งพาความเชี่ยวชาญด้านเทคนิคมากนัก แต่ใช้การหลอกลวงทางจิตวิทยาแทน เป้าหมายของ Social Engineering คือ การหลอกล่อให้เหยื่อเปิดเผยข้อมูลสำคัญ มักอาศัยความไว้วางใจ ความกลัว หรือความเร่งรีบของเหยื่อ เพื่อให้เป้าหมายหลงเชื่อแล้วโน้มน้าวให้เปิดเผยข้อมูลหรือดำเนินการกระทำบางสิ่งบางอย่างเพื่อให้ได้ผลประโยชน์ตามที่ผู้โจมตีต้องการ การโจมตีของ Social Engineering เป็นวิธีการที่ใช้ได้ดีกับกลุ่มเป้าหมายที่ไม่มีความรู้ทางด้านความปลอดภัยทางไซเบอร์\r\nวัตถุประสงค์ของการโจมตีแบบ Social Engineering \r\n1. การเข้าถึงข้อมูลสำคัญ \r\nเช่น รหัสผ่าน บัตรเครดิต ข้อมูลส่วนบุคคล หรือข้อมูลภายในขององค์กร เป็นต้น ผู้โจมตีใช้ข้อมูล\r\n เหล่านี้เพื่อเจาะระบบ เพิ่มสิทธิ์การเข้าถึง หรือนำไปขายเพื่อแสวงหารายได้ \r\n2. การเจาะระบบหรือเครือข่ายองค์กร \r\nหลอกให้เหยื่อเปิดลิงก์หรือไฟล์ที่มีมัลแวร์ ส่งผลให้มัลแวร์ติดตั้งในระบบเครือข่ายขององค์กร \r\nใช้ข้อมูลรับรอง (Credentials) ที่ได้มาเพื่อเข้าควบคุมระบบขององค์กร \r\n3. การก่อให้เกิดความเสียหายทางการเงิน \r\nเช่น โอนเงินโดยไม่รู้ตัวผ่านการหลอกลวง หรือขโมยเงินจากบัญชีธนาคาร สร้างธุรกรรมปลอม \r\nเช่น การซื้อสินค้าหรือบริการ \r\n4. การขโมยตัวตน (Identity Theft) \r\nใช้ข้อมูลส่วนตัว เช่น หมายเลขบัตรประชาชน วันเกิด หรือข้อมูลติดต่อ เพื่อปลอมตัวเป็นเหยื่อ \r\nใช้ในการเปิดบัญชีธนาคาร ทำธุรกรรม หรือกระทำผิดกฎหมายในนามของเหยื่อ \r\n5. การสร้างความวุ่นวายและลดความน่าเชื่อถือ \r\nการเผยแพร่ข้อมูลเท็จหรือข้อมูลภายในองค์กรเพื่อทำให้เสียชื่อเสียง ทำลายความไว้วางใจใน\r\n องค์กร เช่น การปลอมอีเมลจากผู้บริหารเพื่อสั่งการผิดๆ \r\n6. การรวบรวมข้อมูลเพื่อโจมตีเพิ่มเติม \r\nใช้ข้อมูลที่ได้มาวางแผนการโจมตีที่ซับซ้อนยิ่งขึ้น เช่น การโจมตีด้วยวิศวกรรมสังคมหลายขั้นตอน \r\n7. การใช้เป็นฐานข้อมูลสำหรับการขายในตลาดมืด \r\nข้อมูลที่ได้จากการโจมตีมักถูกนำไปขายต่อให้ผู้ไม่หวังดีรายอื่นในตลาดใต้ดิน \r\n8. การแบล็กเมล์หรือข่มขู่ \r\nข้อมูลส่วนตัวหรือข้อมูลที่อ่อนไหวสามารถถูกใช้เพื่อแบล็กเมล์เหยื่อ เช่น ขู่ว่าจะเปิดเผยข้อมูล\r\n หากไม่จ่ายเงิน \r\n', 'image.png', 1),
(7, 'Phishing', '                Phishing คือ วิธีการที่นิยมและพบได้บ่อยที่สุด เป็นการหลอกลวงขโมยข้อมูลส่วนบุคคลของเป้าหมายจากการสร้างสถานการณ์ เช่น การส่งข้อความ SMS , Email หรือ การ Fake website ที่ทำให้ดูมีความน่าเชื่อถือเพื่อหลอกล่อให้เป้าหมายเชื่อ แล้วทำการกรอกข้อมูลส่วนบุคคล เช่น เลขบัตรประชาชน รหัสผ่าน OTP หรือเลขที่ Passport รวมถึงให้ทำธุรกรรมต่างๆตามที่ผู้โจมตีต้องการเพื่อขโมยข้อมูลของเป้าหมายมาใช้ประโยชน์ โดยที่ข้อมูลนั้นไม่ได้รับอนุญาตจากเจ้าของข้อมูล โดยคำว่า Phishing มาจากคำว่า Fishing ที่แปลว่า ตกปลา ประเภทของการโจมตี Phishing ที่พบบ่อย มีดังนี้ \r\n\r\n<----------------------------------------------------------------------------------------------------------->\r\n\r\n                 Email Phishing คือการส่งข้อความหลอกลวงผ่านทางอีเมล เป็นการโจมตีรูปแบบหนึ่งที่นิยมและพบบ่อยมาตั้งแต่ยุคแรกๆ โดยผู้โจมตีจะ ส่งอีเมลหลอกลวงโดยอ้างว่ามาจากแหล่งที่น่าเชื่อถือ เพื่อหลอกให้บุคคลเปิดเผยข้อมูลที่ละเอียดอ่อนหรือดำเนินการบางอย่าง โดยอาจจะใช้ความสัมพันธ์ของบุคคล สถาบันการเงิน หรือ องค์กรที่สังกัด เพื่อให้ดูน่าเชื่อถือ ซึ่งเนื้อหาใน Email นั้น อาจบอกถึงความจำเป็นเร่งด่วน ที่จะต้องกรอกข้อมูล หรือแจ้งการให้ข้อมูลส่วนบุคคล เช่น Username หรือ กรอกข้อมูลบัญชีหรือรหัสผ่าน ลักษณะสำคัญของ Email Phishing  \r\n1. ตรวจสอบที่อยู่อีเมลของผู้ส่ง อีเมลที่มาจากแหล่งที่ไม่น่าเชื่อถือหรือโดเมนที่ผิดปกติ เช่น \r\nbank.security123@gmail.com อาจจะเป็นสัญญาณของ Phishing \r\n2. ตรวจสอบลิงก์ อย่าคลิกลิงก์ในอีเมลที่คุณไม่แน่ใจ ลองเอาเมาส์ไปชี้บนลิงก์เพื่อดู URL ที่แท้จริงว่ามา\r\n จากแหล่งที่น่าเชื่อถือหรือไม่ \r\n3. เนื้อหาที่มีข้อผิดพลาด การสะกดคำผิด, รูปภาพผิดปกติ หรือข้อความที่เขียนดูผิดพลาดอาจเป็น\r\n สัญญาณว่าอีเมลนั้นเป็น Phishing \r\n4. การขอข้อมูลที่ไม่สมเหตุสมผล ธนาคารหรือองค์กรที่เชื่อถือไม่ได้ขอข้อมูลส่วนตัวผ่านทางอีเมล\r\n โดยตรง หากได้รับคำขอที่ไม่ปกติ เช่น รหัสผ่านหรือลงทะเบียนข้อมูลทางการเงิน ต้องระวัง \r\n5. อีเมลที่มีอารมณ์เร่งรีบรวบรัด ข้อความที่มักมีลักษณะเร่งด่วนหรือใช้คำที่ทำให้เกิดความเครียด เช่น \r\n\"บัญชีของคุณถูกล็อค\" หรือ \"คุณต้องกรอกข้อมูลทันที\" ถือเป็นสัญญาณที่ต้องระมัดระวัง\r\n \r\nตัวอย่าง Email จริง และ  Email ปลอม ตามรูปภาพที่ 1 และ 2 ตามลำดับ\r\n\r\nความแตกต่างระหว่าง อีเมลจริง และ อีเมล Phishing ในตัวอย่างมีดังนี้ \r\n1. ที่อยู่อีเมลของผู้ส่ง \r\nอีเมลจริง ที่อยู่อีเมลจะเป็นของธนาคารหรือองค์กรที่เชื่อถือได้ เช่น email@realbank.com \r\nอีเมล Phishing ที่อยู่อีเมลมักจะเป็นชื่อโดเมนที่ปลอมแปลง เช่น email@fakebank.com ซึ่งอาจคล้าย\r\n กับโดเมนจริง แต่จะมีการสะกดผิดหรือไม่ตรงกับบริษัทจริง \r\n2. ลิงก์ที่แนบในอีเมล \r\nอีเมลจริง ลิงก์ในอีเมลจะนำไปยังเว็บไซต์ที่ถูกต้องของธนาคารหรือองค์กร เช่น www.realbank.com \r\nอีเมล Phishing ลิงก์มักจะเป็นเว็บไซต์ปลอมที่ดูเหมือนของจริง แต่มีการสะกดผิดหรือเป็นเว็บไซต์ที่ไม่ได้เชื่อมโยงกับธนาคารหรือองค์กรที่ถูกกล่าวถึง เช่น www.fakebank.com \r\n3. การขอข้อมูล \r\nอีเมลจริง ธนาคารจะไม่ขอข้อมูลสำคัญผ่านทางอีเมล เช่น รหัสบัญชี หรือรหัสผ่าน อีเมลจริงจะมักให้\r\n คำแนะนำเกี่ยวกับการเข้าสู่ระบบโดยตรงจากเว็บไซต์ที่แท้จริง \r\nอีเมล Phishing มักจะขอข้อมูลส่วนตัวหรือข้อมูลที่ละเอียดอ่อน เช่น รหัสบัญชี หรือรหัสผ่าน โดยอ้างว่า  มีปัญหาหรือความจำเป็นเร่งด่วน \r\n4. ข้อความในอีเมล \r\nอีเมลจริง เนื้อหามักจะไม่เร่งด่วนและไม่มีการสร้างความกลัว เช่น \"โปรดตรวจสอบรายการธุรกรรมของ\r\n คุณ\" หรือ \"หากคุณมีคำถาม โปรดติดต่อเรา\" \r\nอีเมล Phishing มักจะใช้คำที่เร่งด่วนและสร้างความกลัว เช่น \"กรุณายืนยันข้อมูลภายใน 24 ชั่วโมง \r\nมิฉะนั้นบัญชีของคุณจะถูกระงับ\" \r\n5. รูปแบบของภาษาที่ใช้ \r\nอีเมลจริง ภาษาเป็นทางการและชัดเจน โดยมักมีรูปแบบการเขียนที่ถูกต้อง \r\nอีเมล Phishing ภาษามักจะไม่สมบูรณ์ มีการสะกดคำผิดหรือคำพูดที่ดูไม่เป็นทางการ อาจทำให้เกิด\r\n ความสงสัยได้ \r\n6. ช่องทางการติดต่อ \r\nอีเมลจริง ธนาคารหรือองค์กรที่เชื่อถือได้จะให้ข้อมูลการติดต่อที่ถูกต้อง เช่น หมายเลขโทรศัพท์ หรือที่อยู่ อีเมลของฝ่ายบริการลูกค้า อีเมล Phishing มักจะไม่มีข้อมูลติดต่อที่สามารถตรวจสอบได้จริง หรือบางครั้งอาจให้ลิงก์หรือ ลงทะเบียนเพื่อป้อนข้อมูลส่วนตัว \r\n7. การสร้างความเร่งด่วน \r\nอีเมลจริง ข้อความส่วนใหญ่จะให้คำแนะนำที่ไม่เร่งด่วนหรือมีการดำเนินการภายในระยะเวลาปกติ \r\nอีเมล Phishing จะใช้การสร้างความเร่งด่วนเพื่อให้ผู้รับทำตามคำขอ เช่น \"กรุณาทำการยืนยันข้อมูล\r\n ภายใน 24 ชั่วโมง\" \r\n\r\nวิธีรับมือกับอีเมล Phishing \r\n1. ไม่คลิกลิงก์ในอีเมลที่น่าสงสัย หากได้รับอีเมลที่ดูน่าสงสัย อย่าคลิกลิงก์หรือดาวน์โหลดไฟล์จากอีเมลนั้น ควรเข้าเว็บไซต์ที่แท้จริงโดยตรง โดยลิงก์ดังกล่าวอาจเชื่อมโยงไปยังเว็บไซต์ปลอมและถึงแม้ว่าจะขึ้นต้นด้วย https:// ก็ควรตรวจสอบก่อน ในส่วนของเอกสารหรือไฟล์แนบ ซึ่งวิธีสังเกตคือให้ลองเอาเม้าส์ไปวางที่ลิงก์นั้นโดย ไม่ต้องกด จะเห็นข้อความขึ้นเป็นเส้นทางลิงก์ปลายทาง จะพบว่าลิงก์ปลายทาง ไม่ใช่เว็บไซต์ทางการ แต่เป็นเว็บอื่น \r\n2. ตรวจสอบกับองค์กรที่อ้างถึงในอีเมล หากอีเมลอ้างว่าเป็นจากธนาคารหรือองค์กรใด ๆ ให้โทรติดต่อ\r\n หรือเข้าเว็บไซต์ขององค์กรนั้นโดยตรงเพื่อสอบถาม \r\n3. ใช้ซอฟต์แวร์ป้องกันไวรัสและสแกนระบบ ให้ใช้ซอฟต์แวร์ที่สามารถตรวจจับอีเมล Phishing \r\nและมัลแวร์ได้ \r\n4. เปิดใช้งานการยืนยันตัวตนสองชั้น (2FA) วิธีนี้จะเพิ่มความปลอดภัยในการเข้าใช้บัญชีออนไลน์และ\r\n ทำให้ยากขึ้นสำหรับผู้โจมตีในการเข้าถึงบัญชีของคุณ \r\n5. รายงานอีเมลที่สงสัย หากได้รับอีเมล Phishing ควรรายงานให้บริษัทหรือองค์กรที่เกี่ยวข้องทราบ \r\nเพื่อช่วยป้องกันไม่ให้ผู้อื่นตกเป็นเหยื่อ\r\n\r\n<-----------------------------------------------------------------------------------------------------------> \r\n\r\n                    Web Phishing หรือการหลอกล่อให้ผู้ใช้งานคลิกเข้าไปในเว็บไซต์ที่เป็นสแปม โดยผู้โจมตี จะสร้างเว็บไซต์ขึ้นมาหน้าหนึ่ง แล้วปรับแต่งให้ดูคล้าย ๆ กับเว็บไซต์ขององค์กรที่มีอยู่จริงเพื่อตบตาเหยื่อ วิธีสังเกตคือ URL จะมีส่วนที่ ต่างกันนิดหน่อย เช่น จาก primal.co.th ก็ปลอมแปลงเป็น primal.com ซึ่งถ้าหากไม่ระมัดระวัง พลาดกดเข้าไป ก็อาจกลายเป็นผู้เสียหายได้เลย โดยจุดประสงค์ของเว็บไซต์เหล่านี้คือ การหลอกเอาข้อมูลของผู้ใช้งาน เช่น ยูเซอร์เนม พาสเวิร์ด บัตรประชาชน บัตรเครดิต หรือข้อมูลส่วนตัวอื่น ๆ \r\n\r\nลักษณะสำคัญของ Web Phishing \r\n1. URL ที่ผิดปกติ เว็บไซต์ Phishing มักจะใช้ URL ที่คล้ายกับเว็บไซต์จริง แต่มีการเปลี่ยนแปลงบาง\r\n ตัวอักษรหรือเพิ่มคำที่ทำให้แยกไม่ออก เช่น จาก primal.co.th เป็น primal.com หรือ pr1mal.co.th (ตัวเลข แทนตัวอักษร) ตรวจสอบ URL ทุกครั้งก่อนกรอกข้อมูล โดยเอาเมาส์ไปชี้ที่ลิงก์เพื่อดูว่า URL นั้นถูกต้องหรือไม่ \r\n2. การออกแบบที่ไม่สมบูรณ์หรือผิดปกติ เว็บไซต์ปลอมอาจมีการออกแบบที่ไม่สมบูรณ์ หรือแสดงผล\r\n ผิดปกติ เช่น ภาพหรือฟอนต์ที่ดูแปลก หรือบางส่วนของเว็บไซต์ที่ไม่สามารถทำงานได้ตามปกติ \r\n3. คำขอข้อมูลที่ละเอียดอ่อน เว็บไซต์ Phishing มักจะขอข้อมูลที่ไม่สมควรถาม เช่น รหัสผ่าน, \r\nหมายเลขบัตรเครดิต, หรือหมายเลขบัตรประชาชนผ่านฟอร์มออนไลน์ ซึ่งเว็บไซต์ที่แท้จริงไม่ควรขอข้อมูลเช่นนี้จากผู้ใช้ \r\n4. คำเตือนจากเบราว์เซอร์ เบราว์เซอร์มักจะแจ้งเตือนเมื่อเว็บไซต์มีการเชื่อมต่อที่ไม่ปลอดภัย (เช่น ไม่มี HTTPS หรือใบรับรอง SSL) หรือเมื่อเว็บไซต์นั้นเป็นที่รู้จักว่ามีความเสี่ยง \r\n5. การสร้างความเร่งด่วน เว็บไซต์ Phishing มักจะมีข้อความที่กระตุ้นให้เกิดความเร่งด่วน เช่น \"กรุณา\r\n ยืนยันข้อมูลของคุณภายใน 24 ชั่วโมง\" หรือ \"บัญชีของคุณถูกล็อค กรุณาเข้าสู่ระบบเพื่อปลดล็อคทันที\" \r\n\r\nวิธีรับมือกับ Web Phishing \r\n1. ตรวจสอบ URL ทุกครั้ง ให้ตรวจสอบที่อยู่ของเว็บไซต์ให้ถูกต้องเสมอ และอย่าคลิกลิงก์จากอีเมลหรือข้อความที่ไม่แน่ใจ ทุกครั้งก่อนกรอกข้อมูล โดยเอาเมาส์ไปชี้ที่ลิงก์เพื่อดูว่า URL นั้นถูกต้องหรือไม่ในกรณีที่เป็นลิงก์ ประเภท URL Shortener เช่น bit.ly, goo.gl, หรือ tinyurl.com \r\n2. ใช้บริการขยายลิงก์ (Expand URL) ใช้เว็บไซต์หรือเครื่องมือขยายลิงก์ เช่น CheckShortURL \r\nUnshorten.It เพื่อดู URL ต้นทางก่อนคลิกลิงก์ \r\n3.  ตรวจสอบผ่านโปรแกรมป้องกันไวรัส โปรแกรมป้องกันไวรัสหลาย สามารถตรวจสอบความปลอดภัย\r\n ของลิงก์ได้ \r\n4. ดูข้อมูลลิงก์ผ่านบริการของ Shortener เพิ่ม \"+\" หลัง URL สำหรับบางบริการ เช่น\r\n bit.ly/example+ จะเปิดหน้ารายละเอียดของลิงก์ \r\n5. ใช้เครื่องมือป้องกันการ Phishing ใช้ซอฟต์แวร์ป้องกันมัลแวร์หรือเบราว์เซอร์ที่มีการป้องกัน \r\nPhishing เพื่อลดความเสี่ยงจากเว็บไซต์ที่เป็นอันตราย \r\n6. ไม่กรอกข้อมูลส่วนตัวในเว็บไซต์ที่ไม่แน่ใจ อย่ากรอกข้อมูลส่วนตัว เช่น รหัสผ่าน หรือข้อมูลบัตร\r\n เครดิตในเว็บไซต์ที่ดูไม่น่าเชื่อถือ \r\n7. ใช้การยืนยันตัวตนสองชั้น (2FA) เปิดใช้งานการยืนยันตัวตนสองชั้นในบัญชีที่รองรับ เพื่อเพิ่มความ\r\n ปลอดภัยหากบัญชีถูกโจมตีจากเว็บไซต์ Phishing \r\n8. ระมัดระวังคำขอที่ผิดปกติ หากเว็บไซต์ขอข้อมูลที่ไม่สมเหตุสมผล เช่น รหัสผ่านหรือข้อมูลส่วนตัวที่ไม่ควรถามผ่านหน้าเว็บ ให้หยุดทำการและตรวจสอบเว็บไซต์นั้นทันที \r\n9. ตรวจสอบชื่อโดเมน ชื่อโดเมนควรตรงกับเนื้อหาที่เกี่ยวข้องและไม่ดูแปลกปลอมหรือหลอกลวง\r\n\r\n<----------------------------------------------------------------------------------------------------------->\r\n\r\n                     Spear phishing คือการหลอกลวงทางไซเบอร์ที่พุ่งเป้าไปยังกลุ่มเป้าหมายหรือบุคคลเฉพาะเจาะจงโดยผู้โจมตีมักเป็นแฮกเกอร์มืออาชีพที่เก็บข้อมูลส่วนตัวของเหยื่อ หรืออาจแฝงตัวเข้าถึงข้อมูลในองค์กร เพื่อให้เนื้อหาในอีเมลดูน่าเชื่อถือยิ่งขึ้น เช่น ใช้ชื่อและอีเมลที่คล้ายกับบุคคลที่เหยื่อรู้จัก เพื่อสร้างความน่าเชื่อถือ ทำให้เหยื่อไม่ทันระวัง ตัวอย่างเช่น อาชญากรอาจส่งอีเมลปลอมที่ดูเหมือนส่งจากเพื่อนร่วมงาน โดยใช้อีเมล \"primal@gmail.com\" แทนที่จะเป็นอีเมลบริษัทจริง ๆ เพื่อให้เหยื่อตกหลุมพราง \r\n\r\nลักษณะสำคัญของ Spear Phishing \r\n1. มีเป้าหมายเฉพาะเจาะจง โจมตีมุ่งเป้าไปที่บุคคล กลุ่มคน หรือองค์กรโดยเฉพาะ ผู้โจมตีใช้ข้อมูล\r\n ส่วนตัวหรือข้อมูลองค์กรที่เก็บรวบรวมมา เพื่อสร้างความน่าเชื่อถือ \r\n2. เนื้อหาที่ปรับแต่งเฉพาะ อีเมลหรือข้อความมักถูกออกแบบให้ดูเหมือนมาจากแหล่งที่เชื่อถือได้ เช่น \r\nเพื่อนร่วมงาน หัวหน้างาน หรือองค์กรที่เกี่ยวข้อง เนื้อหามักจะมีข้อมูลที่เกี่ยวข้องกับเป้าหมาย เช่น ชื่อ โปรเจคที่ทำหรือข้อมูลส่วนตัว \r\n3. การสร้างความเร่งด่วน ข้อความมักกระตุ้นให้ผู้รับตอบสนองอย่างรวดเร็ว เช่น การแจ้งเตือนปัญหา\r\n บัญชี หรือคำขอข้อมูลด่วน \r\n4. ใช้ลิงก์หรือไฟล์แนบที่เป็นอันตราย ลิงก์นำไปยังเว็บไซต์ปลอมที่หลอกให้ใส่ข้อมูลสำคัญ \r\nไฟล์แนบอาจมีมัลแวร์ที่ใช้โจมตีระบบ \r\n5. การแฝงตัวเพื่อหลีกเลี่ยงการตรวจจับ ผู้โจมตีใช้โดเมนที่คล้ายกับของจริง หรือปลอมแปลงที่อยู่อีเมลให้ดูเหมือนถูกต้อง\r\n \r\nวิธีรับมือกับ Spear Phishing \r\n1. ไม่คลิกลิงก์จากแหล่งที่ไม่คุ้นเคย หากคุณได้รับอีเมลที่มีลิงก์หรือไฟล์แนบจากบุคคลที่คุณไม่คุ้นเคยให้หยุดและตรวจสอบ \r\n2. ตรวจสอบที่อยู่อีเมล ตรวจสอบที่อยู่อีเมลให้แน่ใจว่าเป็นแหล่งที่เชื่อถือได้ \r\n3. ใช้การยืนยันตัวตนสองชั้น (2FA) เปิดใช้งานการยืนยันตัวตนสองชั้นในระบบที่รองรับ เพื่อเพิ่มความ\r\n ปลอดภัย\r\n\r\n<----------------------------------------------------------------------------------------------------------->\r\n\r\n                   Smishing หรือ SMS Phishing เป็นการหลอกลวงผ่านข้อความ SMS วิธีสังเกต ข้อความเหล่านี้จะถูกส่งมาจากเบอร์แปลกที่เป็นเบอร์ส่วนตัวของบุคคลทั่วไป อ้างว่าส่งมาจากองค์กรใหญ่ ๆ ซึ่งไม่สมเหตุสมผล บางทีเป็นข้อความที่ใช้ภาษาไม่เป็นทางการ พิมพ์ผิด หรือเป็นข้อความที่อ้างว่าเราได้รางวัล หรือทำให้งงงวย เช่น “พัสดุของคุณจัดส่งไม่สำเร็จ กรุณาคลิกลิงก์เพื่อดำเนินการจัดส่งต่อ” คนที่สั่งของออนไลน์บ่อย ๆ ก็อาจจะหลงกลแล้วคลิกเข้าไป กรอกข้อมูลต่าง ๆ เพราะคิดว่าเป็น SMS จากขนส่งจริง หรืออาจจะเป็น SMS ที่หลอกล่อให้เราคลิกเข้าไปในเว็บไซต์ปลอมที่มิจฉาชีพสร้างขึ้นก็ได้ \r\n\r\nลักษณะสำคัญของ Smishing \r\n1. ส่งข้อความจากเบอร์แปลก มักเป็นเบอร์โทรศัพท์ส่วนตัวที่ไม่เกี่ยวข้องกับองค์กรจริง \r\n2. ใช้ข้อความที่ดูเร่งด่วน เช่น การแจ้งปัญหาที่ต้องแก้ไขทันที หรือการแจ้งว่าคุณได้รับรางวัล \r\n3. ลิงก์ที่ดูไม่น่าเชื่อถือ ลิงก์ที่ส่งมามักเป็นโดเมนปลอมหรือย่อ URL ให้ดูเหมือนน่าเชื่อถือ เช่น \r\nbit.ly/abc123 \r\n4. ข้อความที่ไม่เป็นทางการหรือมีข้อผิดพลาด เช่น การพิมพ์ผิดหรือใช้ภาษาที่ดูไม่เป็นทางการ \r\n5. ลักษณะข้อความมีเนื้อหาที่เกี่ยวข้องกับเหยื่อ เช่น การแจ้งปัญหาเกี่ยวกับพัสดุ, การยืนยันบัญชี\r\n ธนาคาร, หรือการแจ้งเตือนจากหน่วยงานราชการ \r\n\r\nตัวอย่างข้อความ Smishing \r\n1. การหลอกเกี่ยวกับพัสดุ \r\n“พัสดุของคุณจัดส่งไม่สำเร็จ กรุณาคลิกลิงก์นี้เพื่อดำเนินการจัดส่งใหม่ [bit.ly/fakeparcel]” \r\n2. การแจ้งเตือนจากธนาคารปลอม \r\n“บัญชีของคุณถูกระงับชั่วคราว กรุณาเข้าสู่ระบบเพื่อยืนยันข้อมูล: [fakebank.com/login]” \r\n3. การแจ้งเตือนว่าได้รับรางวัล \r\n“ยินดีด้วย! คุณได้รับ iPhone 15 ฟรี กรุณาคลิกที่นี่เพื่อรับของรางวัล [scamlink.com]” \r\n\r\nวิธีป้องกันและรับมือกับ Smishing \r\n1. ไม่คลิกลิงก์ในข้อความแปลก หากข้อความมาจากแหล่งที่ไม่รู้จัก ให้หลีกเลี่ยงการคลิกลิงก์ในข้อความ \r\n2. ติดต่อองค์กรโดยตรง หากสงสัยว่าเป็นข้อความปลอม ให้ติดต่อองค์กรผ่านช่องทางที่เป็นทางการ เช่น เว็บไซต์หรือเบอร์โทรที่ได้รับการยืนยัน \r\n3. ติดตั้งซอฟต์แวร์ป้องกันมัลแวร์ ใช้แอปพลิเคชันที่ช่วยตรวจจับลิงก์หรือข้อความอันตราย \r\n4. อย่าให้ข้อมูลส่วนตัวผ่านข้อความ องค์กรที่น่าเชื่อถือจะไม่ขอข้อมูลส่วนตัว เช่น รหัสผ่าน หรือข้อมูล\r\n บัตรเครดิต ผ่าน SMS \r\n5. รายงานข้อความหลอกลวง หากได้รับข้อความที่น่าสงสัย สามารถแจ้งเบอร์โทรศัพท์หรือข้อความนั้น\r\n ต่อผู้ให้บริการโทรศัพท์มือถือหรือหน่วยงานที่เกี่ยวข้องเพื่อตรวจสอบ\r\n\r\n<----------------------------------------------------------------------------------------------------------->\r\n\r\n                        Voice Phishing คือการหลอกลวงทางไซเบอร์ในรูปแบบเสียง โดยผู้โจมตีมักใช้การโทรศัพท์เพื่อหลอกล่อให้เหยื่อเปิดเผยข้อมูลส่วนตัวหรือโอนเงินให้ ซึ่งในปัจจุบันเป็นที่รู้จักในชื่อ \"แก๊งคอลเซ็นเตอร์\" ตัวอย่างวิธีการ Vishing เช่น อ้างว่าโทรมาจากองค์กรสำคัญ ปลอมเป็นคนรู้จัก อ้างว่าเหยื่อได้รับรางวัลหรือของสมนาคุณ เป็นต้น เมื่อเหยื่อตกหลุมพราง ผู้โจมตีมักขอข้อมูลสำคัญ เช่น หมายเลขบัตรประชาชน เลขบัญชีธนาคาร หรืออาจขอให้โอนเงินเข้าไปในบัญชีของพวกเขา \r\n\r\nลักษณะสำคัญของ Voice Phishing \r\n1. แสดงตัวว่าเป็นบุคคลหรือองค์กรที่น่าเชื่อถือ เช่น ปลอมเป็นเจ้าหน้าที่ธนาคาร, หน่วยงานรัฐ, บริษัท\r\n ที่เหยื่อเกี่ยวข้อง หรือ อ้างว่าโทรมาจากองค์กร เช่น สรรพากร, ตำรวจ, หรือศาล \r\n2. สร้างสถานการณ์ที่เร่งด่วน แจ้งว่าเหยื่อมีคดีความ, หนี้สิน, หรือข้อมูลสำคัญรั่วไหล ขู่ว่าจะมี\r\n ผลกระทบร้ายแรงหากไม่ดำเนินการทันที เช่น การอายัดบัญชี \r\n3. มีการโน้มน้าว ใช้ข้อมูลส่วนตัวของเหยื่อ (เช่น ชื่อ-สกุล หรือหมายเลขบัญชีบางส่วน) เพื่อสร้างความน่าเชื่อถือ อ้างว่ามีรางวัลหรือสิทธิพิเศษ เช่น การได้รับเงินคืนหรือของขวัญ \r\n4. ขอข้อมูลสำคัญหรือการโอนเงิน ขอหมายเลขบัตรเครดิต, หมายเลขบัตรประชาชน, หรือรหัส OTP \r\nขอให้โอนเงินเข้าบัญชีของผู้โจมตี \r\n\r\nตัวอย่างสถานการณ์ Voice Phishing \r\n1. ปลอมเป็นเจ้าหน้าที่ธนาคารโทรศัพท์แจ้งว่า \"บัญชีของคุณถูกเข้าถึงโดยไม่ได้รับอนุญาต กรุณาให้หมายเลขบัตรและรหัส OTP เพื่อยืนยันตัวตน มิฉะนั้นบัญชีของคุณจะถูกระงับ\" \r\n2. ปลอมเป็นตำรวจหรือศาลแจ้งว่า \"คุณมีหมายจับในข้อหาฟอกเงิน กรุณายืนยันตัวตนโดยให้ข้อมูลบัตรประชาชนและโอน เงินประกันตัวเพื่อยกเลิกหมายจับ\" \r\n3. อ้างว่าเป็นบริษัทขนส่งโทรแจ้งว่า \"พัสดุของคุณถูกยึดที่ด่านศุลกากร กรุณาชำระค่าธรรมเนียมด่วน มิฉะนั้นพัสดุจะถูกทำลาย\" \r\n4. ปลอมเป็นคนรู้จักผู้โจมตีอาจอ้างว่าเป็นเพื่อนหรือญาติ โทรมาขอความช่วยเหลือ เช่น \"ฉันมีปัญหาเรื่องการเงินด่วนขอให้คุณโอนเงินมาให้ก่อน\" \r\n\r\nวิธีรับมือกับ Voice Phishing \r\n1. อย่าให้ข้อมูลส่วนตัวทางโทรศัพท์ องค์กรที่น่าเชื่อถือจะไม่ขอข้อมูลสำคัญ เช่น รหัส OTP หรือ\r\n รหัสผ่านทางโทรศัพท์ \r\n2. ตั้งสติและไม่ตื่นตระหนก หากได้รับสายที่อ้างถึงสถานการณ์เร่งด่วน ให้หยุดและตรวจสอบข้อเท็จจริงก่อน \r\n3. ติดต่อกลับองค์กรโดยตรง หากสงสัย ให้โทรไปยังหมายเลขที่ได้รับการยืนยันจากเว็บไซต์ทางการขององค์กร\r\n 4. บล็อกหมายเลขโทรศัพท์ต้องสงสัย ใช้ฟีเจอร์บล็อกหมายเลขหรือรายงานไปยังผู้ให้บริการโทรศัพท์ \r\n5. รายงานการหลอกลวง หากคุณตกเป็นเหยื่อ หรือได้รับสายหลอกลวง ให้แจ้งตำรวจหรือหน่วยงานที่\r\n เกี่ยวข้อง เช่น สำนักงานคุ้มครองผู้บริโภค\r\n', 'simage1.png, simage2.png', 1),
(8, 'SPAM', '                   Spam (สแปม) คือ อีเมลหรือข้อความโฆษณาหรือเนื้อหาที่ส่งให้ผู้รับโดยไม่ได้รับอนุญาต มักไม่ระบุชื่อ ผู้ส่งที่ชัดเจนหรือมีการแอบอ้าง ทำให้ก่อความรำคาญแก่ผู้รับ มักจะเป็นข้อความโฆษณา, การเสนอขายผลิตภัณฑ์ หรือบริการ, หรือการหลอกลวง \r\n \r\nลักษณะสำคัญของ Spam \r\n1. ส่งในปริมาณมาก มักถูกส่งไปยังกลุ่มผู้รับจำนวนมากในคราวเดียว โดยไม่มีการกำหนดเป้าหมาย\r\n เฉพาะเจาะจง \r\n2. ไม่ได้รับการร้องขอ ผู้รับมักไม่ได้อนุญาตหรือแสดงความต้องการที่จะรับข้อความนั้น \r\n3. มีจุดประสงค์เชิงพาณิชย์หรือไม่พึงประสงค์ เนื้อหามักเกี่ยวกับการโฆษณาสินค้า บริการ หรือการโปร\r\n โมตเว็บไซต์ ในบางกรณีอาจเป็นการหลอกลวง เช่น การเสนอรางวัลปลอม \r\n4. อาจแฝงภัยคุกคาม มีลิงก์ที่นำไปสู่เว็บไซต์ปลอมหรือไฟล์แนบที่เป็นมัลแวร์ ใช้หลอกลวงให้ผู้รับให้ข้อมูลส่วนตัว เช่น รหัสผ่านหรือข้อมูลทางการเงิน \r\n\r\nประเภทของ Spam ที่พบได้บ่อย มีดังนี้ \r\n1. Email Spam  \r\nโดยจะส่งผ่านทางอีเมล อีเมล Spam สามารถมีลิงก์ที่อาจนำไปสู่เว็บไซต์ที่อันตรายหรือมีการ\r\n แอบอ้างเป็นองค์กรที่เชื่อถือได้ ตัวอย่าง อีเมลโฆษณาสินค้า เช่น ยาลดน้ำหนัก, สินค้าอุปโภคบริโภค อีเมลปลอมที่แอบอ้างเป็นธนาคารหรือองค์กร เช่น \"บัญชีของคุณถูกระงับ กรุณาคลิกที่นี่เพื่อแก้ไข\" \r\n2. SMS Spam \r\nข้อความ Spam ที่ส่งผ่านทาง SMS โดยมักจะเป็นข้อความที่เสนอขายผลิตภัณฑ์หรือบริการที่ไม่\r\n เกี่ยวข้อง หรือข้อความที่มีลิงก์เพื่อหลอกให้ผู้รับคลิก ตัวอย่าง เช่น \"คุณได้รับรางวัล iPhone 15 คลิกที่นี่เพื่อรับ [bit.ly/fakesite]\" \r\n3. Application Spam \r\nSpam ที่ถูกส่งผ่านทางแอปพลิเคชันแชท เช่น WhatsApp หรือ Facebook Messenger ซึ ่ง\r\n มักจะเป็นข้อความที่ไม่พึงประสงค์หรือโฆษณาที่ไม่เกี่ยวข้อง ตัวอย่าง เช่น \"อยากหารายได้เสริมวันละ 5,000 บาท คลิกเลย [scamlink.com]\"  \r\n\r\nวิธีรับมือกับ Spam \r\n1. ใช้ตัวกรองสแปมในอีเมลหรือบล็อกเบอร์โทรศัพท์ที่ส่งข้อความสแปม \r\n2. หลีกเลี่ยงการให้ที่อยู่อีเมลเบอร์โทรศัพท์กับเว็บไซต์ที่ไม่น่าเชื่อถือ \r\n3. อย่าเปิดไฟล์แนบหรือคลิกลิงก์ในอีเมลหรือข้อความที่น่าสงสัย \r\n4. ตั้งค่าความเป็นส่วนตัวในแอปพลิเคชัน ', 'image.png', 1),
(9, 'Baiting', '                    Baiting เป็นหนึ่งในภัยคุกคามทางไซเบอร์ที่พบได้บ่อยบนอินเทอร์เน็ตโดย\"เป็นเทคนิคที่แฮกเกอร์ใช้ในการแพร่กระจายมัลแวร์และขโมยข้อมูลของผู้ใช้ โดยใช้กลวิธีล่อลวงเพื่อดึงดูดให้เหยื่อคลิกหรือดาวน์โหลดไฟล์ที่ติดมัลแวร์ ซึ่งมีความคล้ายคลึงกับการโจมตีแบบฟิชชิง แต่ต่างกันที่ Baiting มุ่งเน้นการดึงดูดด้วยสิ่งที่ทำให้ผู้ใช้สนใจ\" เช่น การดาวน์โหลดไฟล์หรือโปรแกรมฟรี โดยปกติจะเป็นไฟล์ เสนอ สินค้าราคาถูกหรือน่าสนใจ อย่างที่เรากล่าวไป แต่พวกเขายังสามารถเล่นกับความกลัวด้วยความเร็ว ทำให้ผู้ใช้เห็นว่าต้องคลิกอย่างรวดเร็วเพื่อ แก้ปัญหาเพื่อรับข้อมูลบางประเภท แทนที่จะหลอกให้กรอกข้อมูลสำคัญในเว็บไซต์ปลอมอย่างฟิชชิง ตัวอย่างการ Baiting ที่พบบ่อย เช่น แฟลชไดรฟ์ที่ติดไวรัสวางในที่สาธารณะ และ โฆษณาหลอกลวงที่ให้ดาวน์โหลดโปรแกรมฟรี\r\n   \r\nลักษณะของ Baiting \r\n1. ข้อเสนอที่ดูดีเกินจริง เช่น การแจกโปรแกรมที่ปกติแล้วต้องเสียค่าใช้จ่ายฟรี หรือการแจกของรางวัล\r\n แบบไม่มีเงื่อนไข \r\n2. ไฟล์ดาวน์โหลดจากแหล่งที่ไม่น่าเชื่อถือ เช่น เว็บไซต์ที่ไม่ใช่ผู้ให้บริการอย่างเป็นทางการ \r\n3. การใช้คำกระตุ้นเร่งด่วน เช่น \"ดาวน์โหลดเดี๋ยวนี้ก่อนหมดเขต!\" หรือ \"รับฟรีวันนี้เท่านั้น!\" \r\n4. อุปกรณ์แปลกปลอมในพื้นที่สาธารณะ เช่น แฟลชไดรฟ์หรือซีดีที่วางไว้ในที่ต่าง ๆ \r\n\r\nตัวอย่างของ Baiting \r\n1. แฟลชไดรฟ์หรืออุปกรณ์ USB ที่ถูกทิ้ง ผู้โจมตีวางแฟลชไดรฟ์ที่มีมัลแวร์ในสถานที่สาธารณะ เช่น ลานจอดรถ หรือสำนักงาน เหยื่อหยิบขึ้นมาและเสียบเข้าคอมพิวเตอร์เพื่อตรวจสอบไฟล์ ทำให้มัลแวร์เริ่มทำงาน \r\n2. ข้อเสนอปลอมในอินเทอร์เน็ต โฆษณาที่ให้ดาวน์โหลดเพลง ภาพยนตร์ หรือซอฟต์แวร์ฟรี เมื่อเหยื่อคลิกลิงก์ อาจนำไปสู่เว็บไซต์ที่ติดมัลแวร์หรือขอข้อมูลส่วนตัว \r\n3. อีเมลหรือข้อความล่อใจ ข้อความแจ้งว่าผู้รับได้รับรางวัล เช่น คูปองส่วนลด หรือสินค้าฟรี เมื่อกดลิงก์ หรือดาวน์โหลดไฟล์ อาจทำให้ระบบติดมัลแวร์ \r\n4. การแจกของฟรีในอีเวนต์ การแจก USB ฟรีหรือของที่ระลึกที่ดูน่าเชื่อถือในงานสัมมนาหรืออีเวนต์\r\n อุปกรณ์ดังกล่าวอาจถูกดัดแปลงให้ติดมัลแวร์ \r\n5. โซเชียลมีเดียล่อใจ โพสต์ที่อ้างว่าให้รางวัลสำหรับการกดลิงก์หรือแชร์ต่อ เช่น \"คลิกที่นี่เพื่อรับ iPhone ฟรี\" เหยื่ออาจถูกนำไปสู่ฟิชชิ่งหรือการดาวน์โหลดซอฟต์แวร์ที่ไม่ปลอดภัย \r\n\r\nวิธีรับมือกับ Baiting \r\n1. ไม่ดาวน์โหลดไฟล์หรือโปรแกรมจากแหล่งที่ไม่น่าเชื่อถือ เลือกดาวน์โหลดจากเว็บไซต์ทางการหรือ\r\n ผู้พัฒนาที่น่าเชื่อถือ \r\n2. ไม่เสียบอุปกรณ์ที่ไม่รู้แหล่งที่มาเข้ากับคอมพิวเตอร์ หากพบแฟลชไดรฟ์ในที่สาธารณะ อย่าเสียบเข้าคอมพิวเตอร์โดยไม่ได้ตรวจสอบ \r\n3. ไม่ใช้โปรแกรมป้องกันมัลแวร์และอัปเดตระบบปฏิบัติการ เพื่อป้องกันมัลแวร์ที่แฝงมาในไฟล์ดาวน์โหลด \r\n4. ระวังโฆษณาและป๊อปอัพบนเว็บไซต์ อย่าคลิกที่ป๊อปอัพที่ไม่รู้จัก \r\n5. ฝึกความระมัดระวัง ตั้งคำถามทุกครั้งเมื่อพบข้อเสนอที่ดูดีเกินจริง หรือสถานการณ์ที่ดูน่าสงสัย ', 'image.png', 1),
(10, 'Pretexting', '                   Pretexting เป็นเทคนิคการโจมตีที่ใช้ Social Engineering โดยมุ่งเน้นการสร้างความไว้วางใจระหว่างผู้โจมตีและเป้าหมาย เพื่อหลอกลวงให้เหยื่อเปิดเผยข้อมูลส่วนตัวหรือข้อมูลสำคัญอื่น ๆ ผู้โจมตีมักใช้เรื่องราวที่น่าเชื่อถือหรือแอบอ้างตัวเป็นบุคคลหรือองค์กรที่น่าเชื่อถือ เช่น ธนาคาร, บริษัท, หรือหน่วยงานราชการ เพื่อให้เหยื่อหลงเชื่อและมอบข้อมูลที่สำคัญโดยไม่ทันระวัง\r\n \r\nลักษณะของ Pretexting \r\n1. การแอบอ้างตัวตน   ผู้โจมตีอาจแอบอ้างเป็นเจ้าหน้าที่จากธนาคาร, ผู้ให้บริการอินเทอร์เน็ต, หรือหน่วยงานราชการโดยใช้ข้ออ้างว่าจำเป็นต้องตรวจสอบหรือยืนยันข้อมูล เช่น โทรหาเหยื่อและแจ้งว่า \"บัญชีของคุณมีความผิดปกติ กรุณาแจ้งหมายเลขบัตรประชาชนและวันเดือนปีเกิดเพื่อยืนยันตัวตน\"  หรือ ส่งอีเมลปลอมโดยแอบอ้างเป็นหน่วยงานราชการ แจ้งให้เหยื่อกรอกข้อมูลเพื่ออัปเดตระบบ  \r\n2. การสร้างเรื่องราวที่น่าเชื่อถือ  เช่น แจ้งว่าเหยื่อถูกเลือกให้รับสิทธิพิเศษ, แจ้งเตือนว่าบัญชีถูกระงับ หรือมีปัญหาทางการเงินที่ต้องแก้ไขด่วน \r\n3. การรวบรวมข้อมูลทีละน้อย ผู้โจมตีอาจค่อย ๆ ถามข้อมูลเล็ก ๆ น้อย ๆ เช่น ชื่อ, ที่อยู่, หมายเลขโทรศัพท์ และนำไปใช้ในโจมตีถัดไป \r\n\r\nตัวอย่างของ Pretexting \r\n1. แอบอ้างเป็นเจ้าหน้าที่ฝ่ายไอที ผู้โจมตีโทรหาพนักงานในองค์กร โดยอ้างว่าเป็นเจ้าหน้าที่ไอทีที่ต้องการ \"ตรวจสอบระบบ\" หลอกเอาขอข้อมูล เช่น รหัสผ่าน หรือการเข้าถึงระบบ \r\n2. แอบอ้างเป็นเจ้าหน้าที่ธนาคาร โทรหาลูกค้าโดยอ้างว่าพบ \"ธุรกรรมที่น่าสงสัย\" ขอข้อมูลบัตรเครดิต \r\nรหัส OTP หรือข้อมูลส่วนตัว \r\n3. การแอบอ้างเป็นเพื่อนหรือครอบครัว ติดต่อเป้าหมายผ่านโทรศัพท์หรือข้อความ โดยอ้างว่าเป็นเพื่อนหรือญาติที่ตกทุกข์ได้ยาก หลอกให้โอนเงินหรือให้ข้อมูลส่วนตัว \r\n\r\nวิธีป้องกัน Pretexting \r\n1. ไม่ให้ข้อมูลสำคัญทางโทรศัพท์หรืออีเมล หลีกเลี่ยงการให้ข้อมูลส่วนตัว เช่น หมายเลขบัตรประชาชน , รหัสผ่าน, หรือข้อมูลทางการเงิน หากไม่ได้ยืนยันว่าติดต่อมาจากองค์กรจริง \r\n2. ตรวจสอบข้อเท็จจริงก่อนให้ข้อมูล หากมีการติดต่ออ้างตัวจากหน่วยงานหรือบริษัท ให้โทรกลับไปยังหมายเลขโทรศัพท์ที่ระบุในเว็บไซต์ทางการขององค์กรนั้น \r\n3. สงสัยทุกครั้งเมื่อถูกขอข้อมูลสำคัญ โดยเฉพาะเมื่อผู้ติดต่ออ้างว่าจำเป็นต้องให้ข้อมูลด่วน หรือใช้\r\n ข้ออ้างที่น่าสงสัย \r\n4. ให้ข้อมูลเท่าที่จำเป็น หากหลีกเลี่ยงไม่ได้ ให้จำกัดข้อมูลที่เปิดเผยเฉพาะข้อมูลที่จำเป็น \r\n', 'image.png', 1),
(11, 'Impersonation', '               Impersonation การปลอมตัวเป็นบุคคลอื่น เป็นการกระทำที่ผู้โจมตีแอบอ้างเป็นบุคคลหนึ่งเพื่อหลอกลวงหรือกระทำสิ่งที่สร้างความเสียหาย เช่น การเผยแพร่ข้อมูลที่ไม่เหมาะสม การข่มเหงบุคคลอื่น หรือการกระทำที่ละเมิดสิทธิส่วนบุคคล โดยมีเป้าหมายเพื่อให้ได้ข้อมูลส่วนตัว, เงิน, หรือสร้างความเสียหายแก่ชื่อเสียงของบุคคลนั้น \r\n\r\nลักษณะของImpersonation \r\n1. การเลียนแบบตัวตน ผู้โจมตีสร้างโปรไฟล์ปลอมที่ดูเหมือนบุคคลเป้าหมาย เช่น ชื่อ, รูปภาพ, และ\r\n ข้อมูลที่เกี่ยวข้อง เพื่อสร้างความน่าเชื่อถือ ผู้โจมตีอาจใช้ข้อมูลจริงบางส่วน เช่น ชื่อเพื่อนร่วมงานหรือโครงการที่เหยื่อเกี่ยวข้อง เพื่อทำให้เนื้อหาดูสมจริง \r\n2. การส่งข้อความหลอกลวง ใช้อีเมลหรือข้อความที่มีเนื้อหาเร่งด่วน เช่น ขอให้ดำเนินการโอนเงิน ส่ง\r\n ข้อมูลส่วนตัว หรือคลิกลิงก์ที่แนบมา \r\n3. การใช้บัญชีจริงที่ถูกแฮ็ก ผู้โจมตีเข้าถึงบัญชีที่ถูกแฮ็กแล้วใช้งานในทางที่ผิด เช่น ส่งข้อความหาคน\r\n รู้จักของเหยื่อโดยอ้างว่าเป็นตัวเหยื่อเอง \r\n4. การแอบอ้างเป็นหน่วยงานทางการ ใช้ชื่อและโลโก้ของหน่วยงาน เช่น ธนาคาร รัฐบาล หรือองค์กรที่น่าเชื่อถือ เพื่อขอข้อมูลส่วนตัวหรือเงิน \r\n\r\nตัวอย่าง Impersonation \r\n1. ปลอมเป็นเจ้านาย   ผู้โจมตีส่งอีเมลปลอมที่ดูเหมือนมาจากเจ้านาย ขอให้พนักงานโอนเงินด่วนไปยังบัญชีปลายทาง \r\n2. ปลอมเป็นธนาคาร   ส่งข้อความหรืออีเมลหลอกว่าเหยื่อมีปัญหากับบัญชีธนาคาร และต้องกรอกข้อมูลยืนยันตัวตนผ่านลิงก์ปลอม \r\n3. ปลอมเป็นเพื่อนในโซเชียลมีเดีย  สร้างบัญชีปลอมโดยใช้ชื่อและรูปภาพของเพื่อนเหยื่อ เพื่อหลอกยืมเงินหรือขอข้อมูลส่วนตัว \r\n\r\nวิธีรับมือกับ Impersonation \r\n1. ตรวจสอบตัวตนของผู้ส่ง ตรวจสอบที่อยู่อีเมล, หมายเลขโทรศัพท์, หรือบัญชีที่ติดต่อ หากไม่คุ้นเคยหรือมีลักษณะผิดปกติ ให้ตั้งข้อสงสัยทันที \r\n3. อย่าให้ข้อมูลส่วนตัวง่าย ๆ หลีกเลี่ยงการให้ข้อมูลสำคัญ เช่น รหัสผ่าน, หมายเลขบัญชี, หรือรหัส \r\nOTP ผ่านช่องทางที่ไม่น่าเชื่อถือ \r\n4. ตรวจสอบก่อนดำเนินการ หากมีการขอให้โอนเงินหรือส่งข้อมูลสำคัญ ให้ติดต่อกลับผ่านช่องทางที่\r\n เชื่อถือได้ เช่น โทรศัพท์ไปยังหมายเลขที่ปรากฏบนเว็บไซต์ทางการ \r\n5. ใช้การยืนยันตัวตนแบบสองชั้น (2FA) เพิ่มความปลอดภัยให้กับบัญชีออนไลน์ เช่น อีเมลและโซเชียลมีเดีย \r\n6. อย่าคลิกลิงก์ในข้อความหรืออีเมลที่ไม่น่าเชื่อถือ โดยเฉพาะลิงก์ที่แนบมากับข้อความที่เร่งรัดหรืออ้างว่าเราต้องดำเนินการทันที ', 'image.png', 1),
(12, 'Technical Support Scams', '                     \"การใช้กลยุทธ์ทางด้านเทคนิคต่างๆ มาหลอกเหยื่อ โดยจะให้เหยื่อจ่ายเงินสนับสนุน\" สำหรับการทำงาน ทั้งๆที่แท้จริงแล้ว การทำงานนั้น ไม่มีความจำเป็นที่จะต้องเสียค่าใช้จ่ายเพื่อให้ได้มา โดยมันจะทำการหลอกลวงว่า ซอฟแวร์ หรือระบบ ในเครื่องคอมพิวเตอร์ของเหยื่อกำลังประสบปัญหา หลังจากนั้นจะหลอกให้เหยื่อจ่ายเงินเพื่อทำการแก้ไข  เช่น จากบริษัทซอฟต์แวร์หรือผู้ให้บริการอินเทอร์เน็ต โดยบอกว่าคอมพิวเตอร์ของคุณมีปัญหาและขอเข้าถึงระยะไกลเพื่อแก้ไข แต่จริงๆ แล้วกลับติดตั้งมัลแวร์หรือขโมยข้อมูล\r\n \r\nลักษณะของ Technical Support Scams \r\n1. การแสดงข้อความหลอกลวงบนหน้าจอ แสดงป๊อปอัปแจ้งเตือนปัญหา เช่น \"คอมพิวเตอร์ของคุณติดไวรัส\" พร้อมหมายเลขโทรศัพท์ฝ่ายสนับสนุนปลอม \r\n2. การโทรศัพท์หลอกลวง โทรหาผู้ใช้โดยตรง อ้างว่าคอมพิวเตอร์มีปัญหาหรือระบบเครือข่ายติดไวรัส \r\nและขอเข้าถึงเครื่อง \r\n3. การใช้เว็บไซต์ปลอม สร้างหน้าเว็บไซต์ที่คล้ายกับผู้ให้บริการซอฟต์แวร์ชื่อดัง พร้อมแจ้งเตือนปัญหาและแนะนำให้ติดต่อฝ่ายสนับสนุน \r\n4. การติดตั้งมัลแวร์ หลอกให้เหยื่อติดตั้งซอฟต์แวร์หรือแอปพลิเคชันปลอมเพื่อ \"แก้ไขปัญหา\" แต่จริง ๆ แล้วแฝงมัลแวร์หรือเครื่องมือสอดแนม\r\n \r\nตัวอย่างของ Technical Support Scams \r\n1. ป๊อปอัปปลอมในเว็บไซต์ ข้อความป๊อปอัปแจ้งเตือนว่า \"คอมพิวเตอร์ของคุณติดไวรัส!\" หรือ \"ระบบของคุณถูกล็อก!\" \r\n2. โทรศัพท์แอบอ้างฝ่ายสนับสนุน ผู้โจมตีโทรหาเหยื่อ โดยอ้างว่าเป็นเจ้าหน้าที่จากบริษัทซอฟต์แวร์ เช่น Microsoft หรือ Apple แจ้งว่าเครื่องของเหยื่อมีปัญหาหรือระบบติดไวรัส และเสนอความช่วยเหลือโดยมีค่าบริการ \r\n3. การแชร์หน้าจอระยะไกล (Remote Access) ผู้โจมตีขอให้เหยื่อดาวน์โหลดซอฟต์แวร์สำหรับการ\r\n ควบคุมหน้าจอระยะไกล เช่น TeamViewer หรือ AnyDesk เมื่อเข้าถึงคอมพิวเตอร์ของเหยื่อได้ ผู้โจมตีอาจติดตั้งมัลแวร์ หรือขโมยข้อมูล \r\n\r\nวิธีรับมือ Technical Support Scams \r\n1. อย่าตอบสนองต่อข้อความหรือป๊อปอัปแจ้งเตือนปลอม หากมีข้อความเตือนเกี่ยวกับไวรัสหรือปัญหา \r\nให้ปิดหน้าต่างนั้นทันที \r\n2. ตรวจสอบตัวตนผู้โทร หากได้รับสายจากฝ่ายสนับสนุนที่ไม่คุ้นเคย อย่าให้ข้อมูลส่วนตัวหรือรหัสผ่าน \r\nและตรวจสอบข้อมูลจากเว็บไซต์อย่างเป็นทางการ \r\n3. อย่าให้การเข้าถึงระยะไกล (Remote Access) หลีกเลี่ยงการอนุญาตให้บุคคลที่ไม่น่าเชื่อถือเข้าถึง\r\n อุปกรณ์ของคุณ \r\n4. ติดต่อฝ่ายสนับสนุนโดยตรง หากสงสัยเกี่ยวกับปัญหาทางเทคนิค ให้ติดต่อบริษัทซอฟต์แวร์หรือผู้\r\n ให้บริการอินเทอร์เน็ตผ่านช่องทางที่ได้รับการยืนยัน \r\n5. ติดตั้งซอฟต์แวร์รักษาความปลอดภัย ใช้โปรแกรมป้องกันไวรัสและมัลแวร์ที่น่าเชื่อถือ และอัปเด\r\n ตระบบปฏิบัติการเป็นประจำ', 'image.png', 1),
(13, 'Scareware', '                    เป็นภัยคุกคามด้านความปลอดภัยซอฟต์แวร์ที่เป็นอันตรายเพื่อ \"หลอกลวงผู้ใช้ให้กลัวว่าเครื่องคอมพิวเตอร์หรืออุปกรณ์ของพวกเขามีไวรัสหรือภัยคุกคามด้านความปลอดภัยที่ร้ายแรง ถูกหลอกให้ดาวน์โหลดซอฟต์แวร์ที่แท้จริงแล้วเป็นมัลแวร์ หรือจ่ายเงินเพื่อ \"แก้ไข\" ปัญหาที่ไม่จริง\" โดยทั่วไป Scareware มักจะสร้างข้อความปลอมขึ้นมา เช่น \"คอมพิวเตอร์ของคุณถูกแฮ็ก\" หรือ \"พบไวรัสในระบบ\" และขอให้เหยื่อดาวน์โหลดซอฟต์แวร์หรือชำระค่าบริการเพื่อการกำจัดไวรัส \r\n\r\nลักษณะของ Scareware \r\n1. ข้อความเตือนปลอม แสดงหน้าต่างป๊อปอัปหรือแบนเนอร์ เช่น \"พบไวรัส 3 ตัวในระบบของคุณ! คลิกที่นี่เพื่อแก้ไขทันที\" \r\n2. การหลอกให้ดาวน์โหลดซอฟต์แวร์ปลอม เสนอซอฟต์แวร์ \"กำจัดไวรัส\" ฟรีหรือราคาถูก แต่จริง ๆ \r\nแล้วเป็นมัลแวร์ \r\n3. การหลอกให้จ่ายเงิน อ้างว่าเป็น \"ซอฟต์แวร์ป้องกันไวรัสพรีเมียม\" ที่ต้องจ่ายเงินเพื่อแก้ไขปัญหา  \r\n4. การใช้เว็บไซต์ปลอม เมื่อผู้ใช้คลิกลิงก์ จะถูกเปลี่ยนเส้นทางไปยังเว็บไซต์ที่แสดงข้อความหลอกลวง \r\n\r\nตัวอย่างของ Scareware \r\n1. ป๊อปอัปแจ้งเตือนไวรัสปลอม เมื่อผู้ใช้งานเข้าเว็บไซต์ ป๊อปอัปปรากฏขึ้นพร้อมข้อความว่า \r\n\" คอมพิวเตอร์ของคุณติดไวรัส! คลิกที่นี่เพื่อลบไวรัสทันที \" หากผู้ใช้คลิก จะถูกนำไปยังเว็บไซต์ที่ให้ดาวน์โหลดซอฟต์แวร์ปลอม (ที่อาจเป็นมัลแวร์) หรือขอชำระเงินเพื่อ \"แก้ปัญหา\" \r\n2. โปรแกรมล้างระบบปลอม โปรแกรมที่ผู้ใช้อาจดาวน์โหลดมาใช้งาน โดยอ้างว่าสามารถ \"ทำความสะอาด\" หรือ \"เพิ่มประสิทธิภาพ\" ของคอมพิวเตอร์ หลังการสแกน โปรแกรมจะแสดงผลลัพธ์ปลอมว่าเครื่องมีปัญหามากมาย และเรียกเก็บเงินเพื่อ \"ซ่อมแซม\" \r\n3. อีเมลแจ้งเตือนการละเมิดข้อมูล อีเมลหลอกลวงที่อ้างว่าเป็นจากธนาคารหรือแพลตฟอร์มออนไลน์ \r\nตัวอย่างข้อความ \" บัญชีของคุณถูกเข้าถึงโดยไม่ได้รับอนุญาต! โปรดดาวน์โหลดไฟล์แนบนี้เพื่อตรวจสอบความปลอดภัย \" เมื่อเปิดไฟล์แนบ อาจติดตั้งมัลแวร์ที่ลักลอบเก็บข้อมูลส่วนตัว \r\n\r\nวิธีรับมือ Scareware \r\n1. หลีกเลี่ยงการคลิกลิงก์หรือดาวน์โหลดที่ไม่รู้แหล่งที่มา หากพบข้อความเตือน ให้ปิดหน้าต่างหรือ\r\n เว็บไซต์ทันที \r\n2. ใช้โปรแกรมป้องกันไวรัสที่น่าเชื่อถือ ติดตั้งซอฟต์แวร์จากผู้พัฒนาที่มีชื่อเสียงและอัปเดตเป็นประจำ \r\n3. ตรวจสอบข้อความเตือน ข้อความจาก Scareware มักมีการสะกดผิดหรือภาษาไม่เป็นทางการ \r\n4. อย่าให้ข้อมูลส่วนตัวหรือชำระเงิน หากถูกเรียกร้องให้จ่ายเงิน ตรวจสอบข้อมูลจากแหล่งที่เชื่อถือได้\r\n ก่อน \r\n5. ตรวจสอบเว็บไซต์ที่เข้าใช้งาน หลีกเลี่ยงเว็บไซต์ที่ดูไม่น่าเชื่อถือหรือมี URL ที่แปลก \r\n', 'image.png', 1);

